func (c *Core) massiLookback(optInFastPeriod, optInSlowPeriod int32) int32 {
	if optInFastPeriod == IntegerDefault {
		optInFastPeriod = 9
	} else if optInFastPeriod < 2 || optInFastPeriod > 100000 {
		return -1
	}
	if optInSlowPeriod == IntegerDefault {
		optInSlowPeriod = 25
	} else if optInSlowPeriod < 2 || optInSlowPeriod > 100000 {
		return -1
	}
	return c.emaLookback(optInFastPeriod)*2 + (optInSlowPeriod - 1)
}

