	ema2 := sp.ema2
	ratioRing_Idx := sp.ratioRing_Idx
	total := sp.total
	pkSlot0 := int32(-1)
	var pkVal0 float64
	hl = inHigh - inLow
	ema1 = math.FMA(sp.emaBeta, ema1, float64(sp.optInK_1*hl))
	ema2 = math.FMA(sp.emaBeta, ema2, float64(sp.optInK_1*ema1))
	if ema2 == 0.0 {
		ratio = 1.0
	} else {
		ratio = ema1 / ema2
	}
	pkSlot0 = ratioRing_Idx
	pkVal0 = ratio
	total = total + ratio
	ratioRing_Idx = ratioRing_Idx + 1
